// captureExchangeRT intercepts any /oauth/token POST, records the form, and
// returns a canned identity token — so the ENTIRE_TOKEN path can be tested
// without a real (https) core server.
type captureExchangeRT struct {
	form  url.Values
	token string
}

func (c *captureExchangeRT) RoundTrip(r *http.Request) (*http.Response, error) {
	body, _ := io.ReadAll(r.Body) //nolint:errcheck // test transport
	c.form, _ = url.ParseQuery(string(body))
	resp := &http.Response{
		StatusCode: http.StatusOK,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(fmt.Sprintf(`{"access_token":%q,"token_type":"Bearer","expires_in":3600}`, c.token))),
		Request:    r,
	}
	return resp, nil
}

